    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub archive_hook: Option<String>,
    /// Per-daemon log configuration sub-table.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub logs: Option<PitchforkTomlDaemonLogs>,
}

/// Configuration schema for pitchfork.toml daemon supervisor configuration files.
///
/// Note: When read from a file, daemon keys are short names (e.g., "api").
/// After merging, keys become qualified DaemonIds (e.g., "project/api").
#[derive(Debug, Clone, Default, JsonSchema)]
#[schemars(title = "Pitchfork Configuration")]
pub struct PitchforkToml {
    /// Map of daemon IDs to their configurations
    #[serde(default)]
    pub daemons: IndexMap<DaemonId, PitchforkTomlDaemon>,
    /// Top-level environment variables applied to all daemons as defaults.
    /// Per-daemon `env` overrides these on key conflicts. Values support Tera
//! jq-style log filtering via [jaq](https://github.com/01mf02/jaq).
//!
//! Compiles a jq expression and applies it to each log entry (serialized as
//! a JSON object). Entries for which the filter produces at least one truthy
//! output are retained.

use crate::log_store::LogEntry;
use jaq_core::load::{Arena, File, Loader};
use jaq_core::{self, Ctx, Vars, data, unwrap_valr};
use jaq_json::{self, Val, read::parse_single};

/// A compiled jq filter that can be applied to log entries.
pub struct JqFilter {
    filter: jaq_core::Filter<data::JustLut<Val>>,
}

impl JqFilter {
    /// Compile a jq expression.
    pub fn new(expr: &str) -> miette::Result<Self> {
        let program = File {
            code: expr,
            path: (),
        };
        let defs = jaq_core::defs()
            .chain(jaq_std::defs())
            .chain(jaq_json::defs());
        let funs = jaq_core::funs()
            .chain(jaq_std::funs())
            .chain(jaq_json::funs());
        let loader = Loader::new(defs);
        let arena = Arena::default();
        let modules = loader
            .load(&arena, program)
            .map_err(|e| miette::miette!("jq parse error: {e:?}"))?;
        let filter = jaq_core::Compiler::default()
            .with_funs(funs)
            .compile(modules)
            .map_err(|e| miette::miette!("jq compile error: {e:?}"))?;
        Ok(Self { filter })
    }

    /// Returns true if the filter produces at least one truthy output for
    /// this entry.
    ///
    /// The entry is serialized to a JSON object with all available fields
    /// (timestamp, daemon_id, message, level, msg, logger, fields).
