// docs/api.data.ts
// Data loader for web API endpoints — parses the JSON schema exported by
// `pitchfork api-schema` and makes it available to the VitePress docs site.

import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

interface ApiParam {
  name: string;
  type_name: string;
  description: string;
  required: boolean;
}

interface ApiEndpoint {
  path: string;
  method: string;
  description: string;
  auth: boolean;
  path_params?: ApiParam[];
  query_params?: ApiParam[];
  request_body?: string;
  response_type?: string;
}

interface ApiDoc {
  endpoints: ApiEndpoint[];
}

export default {
  // Rebuild when the generated schema changes.
  watch: ["./public/api-schema.json"],

  async load(): Promise<ApiDoc> {
    const schemaPath = path.resolve(__dirname, "./public/api-schema.json");

    // If the schema hasn't been generated yet (e.g. first clone), return empty.
    if (!fs.existsSync(schemaPath)) {
      console.warn(
        `[api.data.ts] api-schema.json not found at ${schemaPath}. ` +
          `Run 'pitchfork api-schema > docs/public/api-schema.json' to generate it.`
      );
      return { endpoints: [] };
    }

    const raw = fs.readFileSync(schemaPath, "utf-8");
    try {
      return JSON.parse(raw) as ApiDoc;
    } catch (e) {
      console.warn(`[api.data.ts] failed to parse api-schema.json: ${e}`);
      return { endpoints: [] };
    }
  },
};
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { Resvg } from "@resvg/resvg-js";

const fontFile = fileURLToPath(
  new URL("./fonts/SpaceGrotesk.ttf", import.meta.url),
);
const logo = readFileSync(
  new URL("../public/favicon.svg", import.meta.url),
  "utf8",
);
const escapeXml = (value) =>
  String(value).replace(
    /[<>&"']/g,
    (c) =>
      ({
        "<": "&lt;",
        ">": "&gt;",
        "&": "&amp;",
        '"': "&quot;",
        "'": "&apos;",
      })[c],
  );

const fontOptions = { fontFiles: [fontFile], loadSystemFonts: false };
const widths = new Map();
/** Measure visible text bounds using the same font and renderer as the card. */
export function textWidth(text, size) {
  const key = `${size}:${text}`;
  if (!widths.has(key)) {
    const measure = new Resvg(
      `<svg xmlns="http://www.w3.org/2000/svg" width="10000" height="200"><text y="100" font-family="Space Grotesk" font-size="${size}">${escapeXml(text)}</text></svg>`,
      { font: fontOptions },
    );
    widths.set(key, measure.innerBBox()?.width ?? 0);
  }
  return widths.get(key);
}

/** Wrap measured text within the title column, splitting long CLI names when needed. */
export function wrapTitle(title, size = 62, width = 720) {
  const words = String(title)
    .trim()
    .split(/\s+/)
    .flatMap((word) => {
      const chunks = [];
      let chunk = "";
      for (const letter of word) {
        if (chunk && textWidth(chunk + letter, size) > width) {
          chunks.push(chunk);
          chunk = "";
        }
        chunk += letter;
      }
      if (chunk) chunks.push(chunk);
      return chunks;
    });
  const lines = [];
  let line = "";
  for (const word of words) {
    if (line && textWidth(`${line} ${word}`, size) > width) {
      lines.push(line);
      line = word;
    } else line = line ? `${line} ${word}` : word;
  }
  if (line) lines.push(line);
  return lines;
}

/** Render a title card and address it by the final PNG bytes, including renderer changes. */
export function socialCard(title) {
  let size = 62;
  let lines = wrapTitle(title, size);
  if (lines.length > 4) {
    size = 54;
    lines = wrapTitle(title, size);
  }
  if (lines.length > 4) {
    lines = lines.slice(0, 4);
    while (textWidth(`${lines[3]}…`, size) > 720)
      lines[3] = Array.from(lines[3]).slice(0, -1).join("");
    lines[3] += "…";
  }
  const start = 298 - ((lines.length - 1) * (size + 14)) / 2;
  const heading = lines
    .map(
      (line, i) =>
        `<text x="64" y="${start + i * (size + 14)}" font-size="${size}" fill="#f4eee3">${escapeXml(line)}</text>`,
    )
    .join("");
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1200" height="630" viewBox="0 0 1200 630">
    <rect width="1200" height="630" fill="#191313"/>
    <rect width="1200" height="8" fill="#ef4444"/>
    <g font-family="Space Grotesk">
      <text x="64" y="85" font-size="30" fill="#ef4444">pitchfork / docs</text>
      ${heading}
      <path d="M64 508 H1136" stroke="#3d3540"/>
      <text x="64" y="564" font-size="26" fill="#c2b6a4">pitchfork.jdx.dev</text>

