                        MacOSLaunchMode::LaunchAgentUser,
                    )
                } else {
                    (
                        MacOSLaunchMode::LaunchAgentUser,
                        MacOSLaunchMode::LaunchDaemonSystem,
                    )
                };
                (
                    build_launcher(&app_path, current_mode)?,
                    build_launcher(&app_path, other_mode)?,
                    build_launcher(&app_path, MacOSLaunchMode::LaunchAgentSystem)?,
