    #[serde(rename = "waiting")]
    Waiting,
    #[serde(rename = "running")]
    Running,
    #[serde(rename = "stopping")]
    Stopping,
    #[serde(rename = "errored")]
    Errored { code: i32 },
    #[serde(rename = "stopped")]
