use chrono::{Datelike, TimeZone, Utc};
use cron::Schedule;
use std::str::FromStr;

fn main() {
    let from = Utc.with_ymd_and_hms(2026, 9, 4, 0, 0, 0).unwrap();
    for (day, name) in (1..=7).zip(["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]) {
        let numeric = Schedule::from_str(&format!("0 0 0 * * {day}")).unwrap();
        let named = Schedule::from_str(&format!("0 0 0 * * {name}")).unwrap();
        let next = numeric.after(&from).next().unwrap();
        assert_eq!(next, named.after(&from).next().unwrap());
        assert_eq!(next.weekday().to_string(), name);
        println!("{day} = {name}: {next}");
    }
    assert!(Schedule::from_str("0 0 0 * * 0").is_err());
    println!("0 is rejected.");
}

